function X([string]$s){[Security.SecurityElement]::Escape($s)}
function Para([string]$text,[string]$style='Normal',[string]$align='both'){
 if([string]::IsNullOrWhiteSpace($text)){return ''};$size=if($style-eq'Title'){'32'}elseif($style-eq'Heading1'){'28'}elseif($style-eq'Heading2'){'24'}elseif($style-eq'Caption'){'20'}else{'24'};$bold=if($style-in@('Title','Heading1','Heading2')){'<w:b/>'}else{''}
 '<w:p><w:pPr><w:pStyle w:val="'+$style+'"/><w:jc w:val="'+$align+'"/><w:spacing w:after="100" w:line="330" w:lineRule="auto"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/>'+$bold+'<w:sz w:val="'+$size+'"/><w:szCs w:val="'+$size+'"/></w:rPr><w:t xml:space="preserve">'+(X $text)+'</w:t></w:r></w:p>'
}
function Cell([string]$text,[bool]$head=$false){$shade=if($head){'<w:shd w:fill="1F4E78"/>'}else{''};$color=if($head){'<w:color w:val="FFFFFF"/>'}else{''};$bold=if($head){'<w:b/>'}else{''};'<w:tc><w:tcPr><w:tcMar><w:top w:w="80" w:type="dxa"/><w:left w:w="80" w:type="dxa"/><w:bottom w:w="80" w:type="dxa"/><w:right w:w="80" w:type="dxa"/></w:tcMar>'+$shade+'</w:tcPr><w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/>'+$bold+$color+'<w:sz w:val="19"/></w:rPr><w:t>'+(X $text)+'</w:t></w:r></w:p></w:tc>'}
function TableXml($rows){if($rows.Count-lt 1){return ''};$max=($rows|ForEach-Object{$_.Count}|Measure-Object -Maximum).Maximum;$xml='<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="4" w:color="D9D9D9"/><w:left w:val="single" w:sz="4" w:color="D9D9D9"/><w:bottom w:val="single" w:sz="4" w:color="D9D9D9"/><w:right w:val="single" w:sz="4" w:color="D9D9D9"/><w:insideH w:val="single" w:sz="4" w:color="D9D9D9"/><w:insideV w:val="single" w:sz="4" w:color="D9D9D9"/></w:tblBorders></w:tblPr>';for($r=0;$r-lt$rows.Count;$r++){$xml+='<w:tr>';for($c=0;$c-lt$max;$c++){$v=if($c-lt$rows[$r].Count){$rows[$r][$c]}else{''};$xml+=Cell $v ($r-eq 0)};$xml+='</w:tr>'};$xml+='</w:tbl>';return $xml}
function ImageXml($rid,$name,$cx=6000000,$cy=2733333){'<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:drawing><wp:inline xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" distT="0" distB="0" distL="0" distR="0"><wp:extent cx="'+$cx+'" cy="'+$cy+'"/><wp:docPr id="900" name="'+$name+'"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="0" name="'+$name+'"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="'+$rid+'"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'+$cx+'" cy="'+$cy+'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>'}
function Clean([string]$s){$s=$s-replace'\\(textbf|textit|emph|texttt|url)\{([^}]*)\}','$2'-replace'\\(measured|configured|literature)\{([^}]*)\}',''-replace'\\(hypothesis|missing)',''-replace'\\cite\{[^}]+\}',''-replace'\\(label|addcontentsline)\{[^}]*\}(\{[^}]*\})?(\{[^}]*\})?',''-replace'\\ref\{[^}]+\}',''-replace'\\[a-zA-Z]+\*?(\[[^]]*\])?(\{[^}]*\})?',''-replace'\$([^$]+)\$','$1'-replace'~',' '-replace'\\&','&'-replace'\\%','%';return($s-replace'\s+',' ').Trim()}

Add-Type -AssemblyName System.IO.Compression.FileSystem;New-Item -ItemType Directory -Force -Path $temp|Out-Null;[IO.Compression.ZipFile]::ExtractToDirectory($template,$temp)
$tex=Get-Content $source -Raw -Encoding UTF8;$body=$tex.Substring($tex.IndexOf('\end{titlepage}')+15);$body=$body.Substring(0,$body.LastIndexOf('\end{document}'))
# Replace the old text-only Faster R-CNN figure with the complete architecture diagram.
$figs=[regex]::Matches($body,'(?s)\\begin\{figure\}.*?\\end\{figure\}');foreach($m in @($figs)){$v=$m.Value;if($v.Contains('ResNet-50')-and$v.Contains('RPN')){$body=$body.Replace($v,"`n@@IMG_FASTER@@`n@@CAP:Faster R-CNN gồm ResNet-50, FPN, RPN, RoI Align và hai đầu dự đoán.@@`n")}else{$cap=[regex]::Match($v,'\\caption\{([^}]*)\}').Groups[1].Value;$body=$body.Replace($v,"`n@@CAP:$cap@@`n")}}
$body=[regex]::Replace($body,'\\chapter\*?\{([^}]+)\}',"`n@@H1:`$1@@`n");$body=[regex]::Replace($body,'\\section\*?\{([^}]+)\}',"`n@@H2:`$1@@`n");$body=[regex]::Replace($body,'\\subsection\*?\{([^}]+)\}',"`n@@H3:`$1@@`n")
$body=$body-replace'\\begin\{(table\*?|longtable|tabular)\}(\{[^}]*\})?',''-replace'\\end\{(table\*?|longtable|tabular)\}',''-replace'\\(toprule|midrule|bottomrule|endhead)',''
$body=[regex]::Replace($body,'\\caption\{([^}]*)\}',"`n@@CAP:`$1@@`n");$body=$body-replace'\\\\',"`n";$body=[regex]::Replace($body,'(?s)\\begin\{equation\}.*?\\end\{equation\}',"`n[Công thức được trình bày trong bản PDF nguồn.]`n")
$xmlBody=Para 'PHÁT HIỆN VẬT CẢN TRONG ẢNH HƯỚNG TỚI HỖ TRỢ DI CHUYỂN CHO NGƯỜI KHIẾM THỊ' 'Title' 'center';$xmlBody+=Para 'So sánh YOLO11n, YOLO11s và Faster R-CNN trên bộ dữ liệu ROD' 'Heading2' 'center';$xmlBody+=Para 'Sinh viên: Nguyễn Trần Kiên | Mã sinh viên: 12423018 | Lớp: 12423TN' 'Normal' 'center';$xmlBody+=Para 'Giảng viên hướng dẫn: PGS.TS. Nguyễn Minh Tiến' 'Normal' 'center';$xmlBody+=Para 'Hưng Yên - 2026' 'Normal' 'center'
$blocks=$body-split"(`r?`n){2,}";$tableRows=@()
foreach($block in $blocks){$b=$block.Trim();if(-not$b){continue};if($b-match'^@@H1:(.+)@@$'){if($tableRows.Count){$xmlBody+=TableXml $tableRows;$tableRows=@()};$xmlBody+=Para(Clean $matches[1])'Heading1';continue};if($b-match'^@@H2:(.+)@@$'){if($tableRows.Count){$xmlBody+=TableXml $tableRows;$tableRows=@()};$xmlBody+=Para(Clean $matches[1])'Heading2';continue};if($b-match'^@@H3:(.+)@@$'){if($tableRows.Count){$xmlBody+=TableXml $tableRows;$tableRows=@()};$xmlBody+=Para(Clean $matches[1])'Heading2';continue};if($b-eq'@@IMG_FASTER@@'){if($tableRows.Count){$xmlBody+=TableXml $tableRows;$tableRows=@()};$xmlBody+=ImageXml 'rId900' 'Faster R-CNN architecture';continue};if($b-match'^@@CAP:(.+)@@$'){if($tableRows.Count){$xmlBody+=TableXml $tableRows;$tableRows=@()};$xmlBody+=Para(Clean $matches[1])'Caption''center';continue};if($b.Contains('&')){$cells=@($b-split'&'|ForEach-Object{Clean $_}|Where-Object{$_});if($cells.Count-gt1){$tableRows+=,@($cells);continue}};if($tableRows.Count){$xmlBody+=TableXml $tableRows;$tableRows=@()};$clean=Clean $b;if($clean){$xmlBody+=Para $clean}}
if($tableRows.Count){$xmlBody+=TableXml $tableRows}
# Append the newly completed locked TEST result, which was not present in the source PDF.
$xmlBody+=Para 'KẾT QUẢ ĐÁNH GIÁ TEST CUỐI' 'Heading1';$xmlBody+=Para 'Ba mô hình được đánh giá trên cùng 1.611 ảnh và 2.354 đối tượng TEST bằng checkpoint, threshold và protocol đã khóa từ VALID. Không thay đổi mô hình hoặc ngưỡng sau khi xem TEST.'
