Copy-Item $diagram (Join-Path $temp 'word\media\faster_rcnn_architecture.png') -Force;$relsPath=Join-Path $temp 'word\_rels\document.xml.rels';$rels=Get-Content -LiteralPath $relsPath -Raw;$rels=$rels.Replace('</Relationships>','<Relationship Id="rId900" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/faster_rcnn_architecture.png"/></Relationships>');[IO.File]::WriteAllText($relsPath,$rels,(New-Object Text.UTF8Encoding($false)))
if(Test-Path $output){Remove-Item $output -Force};$stream=[IO.File]::Open($output,[IO.FileMode]::Create);$arc=New-Object IO.Compression.ZipArchive($stream,[IO.Compression.ZipArchiveMode]::Create,$false);Get-ChildItem $temp -Recurse -File|ForEach-Object{$name=$_.FullName.Substring($temp.Length+1).Replace('\','/');$entry=$arc.CreateEntry($name,[IO.Compression.CompressionLevel]::Optimal);$a=[IO.File]::OpenRead($_.FullName);$b=$entry.Open();$a.CopyTo($b);$b.Dispose();$a.Dispose()};$arc.Dispose();$stream.Dispose();Remove-Item $temp -Recurse -Force
